record.field:
# ── Qampo Health Check ─────────────────────────────────────────────────
# GET /health — verifies the API is reachable and the apikey is valid.
# Also validates the apikey by calling /devices (health doesn't need auth).
# ────────────────────────────────────────────────────────────────────────

remote = self.remote_id
cfg = {}
try:
    cfg = json.loads(remote.connection_params or '{}')
except Exception:
    cfg = {}

apikey = (cfg.get('apikey') or '').strip()
if not apikey:
    raise Exception(
        "Missing Qampo API key: set 'apikey' in connection_params.")

api_base = (base_url or '').rstrip('/')
hdrs = {
    'apikey': apikey,
    'Accept': 'application/json',
}

# 1. Health check (does not require authentication)
url_health = '%s/health' % api_base
resp = request_retry('GET', url_health, headers=hdrs, timeout=timeout)

if resp.status_code >= 400:
    raise Exception(
        "Qampo health check failed: HTTP %s - %s" % (
            resp.status_code, (resp.text or '')[:500]))

try:
    body = resp.json() if resp.text else {}
except Exception:
    raise Exception("Qampo health check: invalid JSON response")

if body.get('code') != 200:
    raise Exception(
        "Qampo health check error: %s" % str(body)[:500])

# 2. Quick auth validation by calling /devices
url_devices = '%s/devices' % api_base
resp2 = request_retry('GET', url_devices, headers=hdrs, timeout=timeout)

if resp2.status_code >= 400:
    raise Exception(
        "Qampo API key validation failed: HTTP %s - %s" % (
            resp2.status_code, (resp2.text or '')[:500]))

try:
    devices = resp2.json() if resp2.text else []
except Exception:
    raise Exception("Qampo devices: invalid JSON response")

if isinstance(devices, dict) and devices.get('code'):
    raise Exception(
        "Qampo API key error: %s - %s" % (
            devices.get('code'), devices.get('msg', '')))

bag['apikey'] = apikey
bag['device_count'] = len(devices) if isinstance(devices, list) else 0
bag['timezone'] = cfg.get('timezone', 'Europe/Madrid')

# ── Qampo Catalog Sync ───────────────────────────────────────────────── # GET /devices — fetches all stations with sensors and published variables. # Produces an audit JSON attachment with the full catalog. # ────────────────────────────────────────────────────────────────────────
Remote = self.remote_id cfg = {} try: cfg = json.loads(Remote.connection_params or '{}') except Exception: cfg = {}
apikey = bag.get('apikey') or (cfg.get('apikey') or '').strip() if not apikey: raise Exception("Missing Qampo API key in bag or connection_params.")
api_base = (base_url or '').rstrip('/') hdrs = { 'apikey': apikey, 'Accept': 'application/json', }
url = '%s/devices' % api_base resp = request_retry('GET', url, headers=hdrs, timeout=timeout)
if resp.status_code >= 400: raise Exception( "Qampo /devices failed: HTTP %s - %s" % ( resp.status_code, (resp.text or '')[:500]))
try: devices_raw = resp.json() if resp.text else [] except Exception: raise Exception("Qampo /devices: invalid JSON response")
if isinstance(devices_raw, dict) and devices_raw.get('code'): raise Exception( "Qampo /devices error: %s - %s" % ( devices_raw.get('code'), devices_raw.get('msg', '')))
if not isinstance(devices_raw, list): raise Exception( "Qampo /devices: expected a list, got %s" % type(devices_raw).__name__)
# Parse and normalize the catalog catalog = [] total_sensors = 0 total_published = 0
for dev in devices_raw: if not isinstance(dev, dict): continue
node_id = dev.get('id', '') coords = dev.get('coordinates') or {} state = dev.get('state') or {}
# Filter connected sensors only (skip "Not Connected") connected_sensors = [] for s in (dev.get('sensors') or []): if isinstance(s, dict) and s.get('sensor') != 'Not Connected': connected_sensors.append(s) total_sensors += 1
# Published variables (the ones that actually have data) published_vars = [] for pv in (dev.get('publishedVariables') or []): if isinstance(pv, dict): published_vars.append(pv) total_published += 1
time_cfg = dev.get('timeConfiguration') or {}
catalog.append({ 'node_id': node_id, 'owner': dev.get('owner', ''), 'latitude': coords.get('latitude'), 'longitude': coords.get('longitude'), 'gmt_offset': dev.get('gmt'), 'last_connection': state.get('lastConnection', ''), 'battery': state.get('battery', ''), 'rssi': state.get('rssi', ''), 'internal_temp': state.get('intTemp', ''), 'measure_interval_min': time_cfg.get('measureTime', ''), 'send_interval_min': time_cfg.get('sendTime', ''), 'connected_sensors': connected_sensors, 'published_variables': published_vars, 'tags': dev.get('tags', []), })
# ── Create audit attachment ──────────────────────────────────────────── audit = { 'executed_at': fields.Datetime.now(), 'total_devices': len(catalog), 'total_connected_sensors': total_sensors, 'total_published_variables': total_published, 'devices': catalog, }
json_str = json.dumps(audit, ensure_ascii=False, indent=2) encoded = base64.b64encode(json_str.encode('utf-8')) fname = 'qampo_catalog_%s.json' % ( fields.Datetime.now().replace(':', '').replace('-', '').replace(' ', '_'))
att = env['ir.attachment'].create({ 'name': fname, 'datas_fname': fname, 'datas': encoded, 'mimetype': 'application/json', 'res_model': 'remotecontrol', 'res_id': Remote.id, })
Remote.message_post( body=u'[Qampo] Catalog sync: devices=%s connected_sensors=%s ' u'published_variables=%s' % ( len(catalog), total_sensors, total_published), attachment_ids=[att.id], )
bag['catalog'] = catalog bag['catalog_attachment_id'] = att.id bag['catalog_attachment_name'] = fname

# ── Qampo: Build Sensor Plan ───────────────────────────────────────────
# Reads mdm.measurement.device.sensor records linked to this
# remotecontrol and builds the plan for getValues calls.
#
# Each device stores node_id in its remotecontrol_params.
# Each sensor stores variable_label in its remotecontrol_params.
#
# Groups sensors by device (node) for efficient API calls
# (getValues returns all variables per device in one call).
# ────────────────────────────────────────────────────────────────────────

Remote = self.remote_id
Sensor = env['mdm.measurement.device.sensor']
today_str = fields.Date.today()

cfg = {}
try:
    cfg = json.loads(Remote.connection_params or '{}')
except Exception:
    cfg = {}

default_tz = cfg.get('timezone', 'Europe/Madrid')
apikey = bag.get('apikey') or (cfg.get('apikey') or '').strip()
bag['apikey'] = apikey

condition = [
    ('remotecontrol_params', '!=', False),
    ('device_id.remotecontrol_id', '=', Remote.id),
]

if selected_device_ids:
    condition.append(('device_id', 'in', selected_device_ids))

sensors = Sensor.search(condition)

# Build map of sensor_id -> most recent reading (single query)
last_readings_map = {}
if sensors:
    sensor_ids = [s.id for s in sensors]
    cr = env.cr
    cr.execute(
        'SELECT DISTINCT ON (sensor_id) sensor_id, measurement_time '
        'FROM mdm_measurement_device_sensor_reading '
        'WHERE sensor_id IN %s AND active = TRUE '
        'ORDER BY sensor_id, measurement_time DESC',
        (tuple(sensor_ids),)
    )
    for row in cr.fetchall():
        last_readings_map[row[0]] = row[1]

# Build plan grouped by device (node)
# Structure: { node_id: { info, sensors: [...] } }
devices_plan = {}
plan = []

for sensor in sensors:
    device = sensor.device_id

    try:
        sensor_cfg = json.loads(sensor.remotecontrol_params or '{}') or {}
    except Exception:
        sensor_cfg = {}

    try:
        device_cfg = json.loads(device.remotecontrol_params or '{}') or {}
    except Exception:
        device_cfg = {}

    node_id = device_cfg.get('node_id')
    variable_label = sensor_cfg.get('variable_label')

    if not node_id or not variable_label:
        continue

    # Determine start date
    start_cfg = sensor_cfg.get('start_date') or device_cfg.get('start_date')
    last_reading_time = last_readings_map.get(sensor.id)

    if last_reading_time:
        try:
            initial_date = fields.Date.to_string(
                fields.Datetime.from_string(last_reading_time))
        except Exception:
            initial_date = str(last_reading_time)[:10]
    elif start_cfg:
        initial_date = start_cfg[:10]
    else:
        year_str = today_str[:4]
        initial_date = '%s-01-01' % year_str

    if isinstance(initial_date, unicode):
        initial_date = initial_date.encode('utf-8')

    dev_tz = device_cfg.get('timezone', default_tz)

    plan.append({
        'sensor_id': sensor.id,
        'device_id': device.id,
        'node_id': node_id,
        'variable_label': variable_label,
        'timezone': dev_tz,
        'initial_date': initial_date,
    })

    # Group by device for batched getValues calls
    node_key = str(node_id)
    if node_key not in devices_plan:
        devices_plan[node_key] = {
            'node_id': node_id,
            'timezone': dev_tz,
            'device_id': device.id,
            'sensors': [],
        }
    devices_plan[node_key]['sensors'].append({
        'variable_label': variable_label,
        'sensor_id': sensor.id,
        'device_id': device.id,
    })

bag['sensors_plan'] = plan
bag['devices_plan'] = devices_plan
